/* MOTO SHOP · GitHub Pages · demostración local. No procesa cobros ni guarda información en servidor. */
(()=>{'use strict';
const STORAGE='motoshop_pages_v3', SESSION='motoshop_session_v3';
const money=v=>new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN'}).format(Number(v)||0);
const enc=s=>encodeURIComponent(String(s??''));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=s=>esc(s);
const today=()=>{let d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
const ts=()=>new Date().toISOString();
const fmtDate=v=>new Date(v).toLocaleString('es-MX',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});
const localDay=v=>{const d=new Date(v);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
const uid=()=>Date.now()+Math.floor(Math.random()*10000);
const seeds=[
{id:101,nombre:'Casco Integral Race Pro',categoria:'Cascos',precio:1599,stock:16,codigo:'CAS-001',emoji:'⛑️',color:'#f6d9e2',descripcion:'Casco integral para demostrar una compra segura. Visera transparente, diseño deportivo y gran estilo.',imagenes:[],activo:true},
{id:102,nombre:'Guantes de Protección Urban',categoria:'Accesorios',precio:459,stock:30,codigo:'ACC-002',emoji:'🧤',color:'#ded9f7',descripcion:'Guantes cómodos para tus trayectos por la ciudad. Diseño de demostración.',imagenes:[],activo:true},
{id:103,nombre:'Casco Abatible Touring',categoria:'Cascos',precio:2299,stock:11,codigo:'CAS-003',emoji:'🪖',color:'#e6e8ee',descripcion:'Modelo abatible con estilo touring para cada ruta.',imagenes:[],activo:true},
{id:104,nombre:'Aceite Motor 4T',categoria:'Refacciones',precio:219,stock:45,codigo:'REF-004',emoji:'🛢️',color:'#f8dfc9',descripcion:'Lubricante de muestra para mantenimiento de motocicletas.',imagenes:[],activo:true},
{id:105,nombre:'Kit de Cadena y Piñón',categoria:'Refacciones',precio:989,stock:18,codigo:'REF-005',emoji:'⚙️',color:'#d8e8ef',descripcion:'Kit de transmisión para prácticas de inventario y pedidos.',imagenes:[],activo:true},
{id:106,nombre:'Mochila Rider Impermeable',categoria:'Accesorios',precio:749,stock:22,codigo:'ACC-006',emoji:'🎒',color:'#e5dae9',descripcion:'Mochila compacta diseñada para acompañarte en el camino.',imagenes:[],activo:true},
{id:107,nombre:'Luz LED Auxiliar',categoria:'Accesorios',precio:369,stock:38,codigo:'ACC-007',emoji:'💡',color:'#feebbc',descripcion:'Iluminación auxiliar de muestra para el catálogo.',imagenes:[],activo:true},
{id:108,nombre:'Pastillas de Freno',categoria:'Refacciones',precio:349,stock:26,codigo:'REF-008',emoji:'🔧',color:'#d8ece4',descripcion:'Refacción de prueba para el mantenimiento de tu moto.',imagenes:[],activo:true},
{id:109,nombre:'Casco Retro Classic',categoria:'Cascos',precio:1199,stock:14,codigo:'CAS-009',emoji:'🏍️',color:'#f2d7d2',descripcion:'Estilo clásico con acabados modernos y gran personalidad.',imagenes:[],activo:true}];
const demoUsers=[
{id:1,nombre:'Administración Moto Shop',email:'admin@demo.com',hash:'b507f168642baab1367299fb8892371d289c20a3383cd62423ac73f5e632f9ef',role:'admin',activo:true},
{id:2,nombre:'Cliente Demo',email:'cliente@demo.com',hash:'4812c8deaebaba0e923bdafc155b36d33dd1414a5429012f977953d2e50fe2e5',role:'cliente',activo:true}];
const initState=()=>({version:3,productos:structuredClone(seeds),usuarios:structuredClone(demoUsers),pedidos:[],carrito:[],bitacora:[],registros:[],favoritos:[],notificaciones:[],secuencia:1000});
let state;try{state=JSON.parse(localStorage.getItem(STORAGE)||'null');if(!state||state.version!==3||!Array.isArray(state.productos)||!Array.isArray(state.pedidos))state=initState();}catch(e){state=initState();}
let session=null;try{session=JSON.parse(sessionStorage.getItem(SESSION)||'null');}catch(e){};
let currentCategory='Todos',currentSearch='',currentSort='recientes',adminTab='resumen',reportFrom='',reportTo='',currentReceiptId=null,selectedImage=0,toastTimer;
const app=document.getElementById('app'),modalHost=document.getElementById('modalHost'),navAdmin=document.getElementById('navAdmin');
const getUser=()=>state.usuarios.find(u=>u.id===session?.userId&&u.activo)||null;
const isAdmin=()=>getUser()?.role==='admin';
const pById=id=>state.productos.find(p=>p.id===Number(id));
const orderById=id=>state.pedidos.find(p=>p.id===Number(id));
const safeMoney=x=>Number.isFinite(x)?money(x):money(0);
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(state));return true;}catch(e){toast('Almacenamiento del navegador lleno. Usa imágenes pequeñas o elimina productos.','err');return false;}}
function notify(text){state.notificaciones.unshift({id:uid(),fecha:ts(),texto:text,leida:false});state.notificaciones=state.notificaciones.slice(0,90);}
function audit(email,ok){state.bitacora.unshift({fecha:ts(),correo:email,resultado:ok?'ACEPTADO':'DENEGADO'});state.bitacora=state.bitacora.slice(0,100);persist();}
function toast(text,type='ok'){let box=document.getElementById('flash');box.textContent=text;box.className='toast show'+(type==='err'?' err':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.className='toast',4100);}
function route(x){location.hash=x;render();window.scrollTo({top:0,behavior:'instant'});}
function openModal(title,body,large=false){modalHost.innerHTML=`<div class="modal ${large?'lg':''}"><div class="modal-head"><h2>${esc(title)}</h2><button class="modal-close" data-action="close-modal" aria-label="Cerrar">✕</button></div><div class="modal-body">${body}</div></div>`;modalHost.classList.remove('hidden');document.body.style.overflow='hidden';}
function closeModal(){modalHost.classList.add('hidden');modalHost.innerHTML='';document.body.style.overflow='';}
function imgTag(p,cl=''){if(p?.imagenes?.[0])return `<img class="${cl}" src="${attr(p.imagenes[0])}" alt="${attr(p.nombre)}" loading="lazy">`;return `<span class="product-emoji" aria-hidden="true">${esc(p?.emoji||'🏍️')}</span>`;}
function tile(p,cl=''){return `<div class="product-image ${cl}" style="--product-bg:${/^#[0-9a-fA-F]{6}$/.test(p.color)?p.color:'#f6d9e2'}">${imgTag(p)}</div>`;}
function pictureSmall(p){return p?.imagenes?.[0]?`<img class="table-img" src="${attr(p.imagenes[0])}" alt="${attr(p.nombre)}">`:`<span class="table-img" aria-label="Imagen ilustrativa">${esc(p?.emoji||'🏍️')}</span>`;}
function pagesUrl(product){const u=new URL(window.location.href);u.search='';u.hash='';u.searchParams.set('sku',product.id);u.searchParams.set('nombre',product.nombre);u.searchParams.set('precio',Number(product.precio).toFixed(2));u.searchParams.set('stock',product.stock);u.searchParams.set('categoria',product.categoria);u.searchParams.set('icono',product.emoji||'🏍️');return u.toString();}
function qrSrc(url,size=180){return 'https://api.qrserver.com/v1/create-qr-code/?format=png&margin=12&size='+size+'x'+size+'&data='+encodeURIComponent(url);}
function cartLines(){const a=[];for(const c of state.carrito){const p=pById(c.id);if(p&&p.activo&&p.stock>0){const qty=Math.min(Math.max(1,Number(c.cantidad)||1),p.stock);a.push({p,cantidad:qty,total:+(qty*p.precio).toFixed(2)});}}return a;}
function cartTotals(){let items=cartLines();const subtotal=+(items.reduce((s,i)=>s+i.total,0)).toFixed(2);return {items,subtotal,iva:+(subtotal*.16).toFixed(2)};}
function addCart(id,qty=1){const p=pById(id);qty=Number(qty);if(!p||!p.activo||!Number.isInteger(qty)||qty<=0||qty>10000){toast('Producto o cantidad no válidos.','err');return;}
const c=state.carrito.find(c=>c.id===p.id),have=c?c.cantidad:0;if(p.stock<have+qty){toast('No hay suficientes existencias.','err');return;}if(c)c.cantidad+=qty;else state.carrito.push({id:p.id,cantidad:qty});persist();syncHeader();toast(`Agregaste ${qty} × ${p.nombre} al carrito`);}
function updateQty(id,q){let c=state.carrito.find(c=>c.id===Number(id)),p=pById(id);q=Number(q);if(!c||!p)return;if(!Number.isInteger(q)||q<1||q>p.stock){toast('Ingresa una cantidad válida según el inventario.','err');render();return;}c.cantidad=q;persist();render();}
function removeCart(id){state.carrito=state.carrito.filter(c=>c.id!==Number(id));persist();render();}
function syncHeader(){const u=getUser();document.getElementById('accountLabel').textContent=u?u.nombre.split(' ')[0]:'Iniciar sesión';navAdmin.classList.toggle('hidden',!isAdmin());document.getElementById('mobileAdmin').classList.toggle('hidden',!isAdmin());document.getElementById('cartCount').textContent=state.carrito.reduce((sum,c)=>sum+(Number(c.cantidad)||0),0);document.querySelectorAll('[data-nav]').forEach(n=>n.classList.toggle('active',location.hash.replace('#','')===n.dataset.nav));document.getElementById('year').textContent=new Date().getFullYear();document.getElementById('themeToggle').textContent=document.body.classList.contains('night')?'☀':'☾';}
function banner(){return `<div class="demo-info">🧪 <strong>Demo interactiva:</strong> ningún pago, envío o correo es real. Los datos de compras, inventario y cuentas se guardan solo en este navegador; no se comparten entre visitantes.</div>`;}
function card(p){const available=p.activo&&p.stock>0;let fav=state.favoritos.includes(p.id);return `<article class="product-card"><div class="product-image" style="--product-bg:${/^#[0-9a-fA-F]{6}$/.test(p.color)?p.color:'#f6d9e2'}" data-action="product" data-id="${p.id}">${imgTag(p)}<span class="product-flag pill ${available?'positive':'neutral'}">${available?'Disponible':'Agotado'}</span><button class="favorite ${fav?'saved':''}" type="button" data-action="favorite" data-id="${p.id}" aria-label="Guardar favorito">${fav?'♥':'♡'}</button></div><div class="product-body"><span class="category">${esc(p.categoria)} · ${esc(p.codigo||'')}</span><h3><a href="#producto/${p.id}">${esc(p.nombre)}</a></h3><p>${esc(p.descripcion)}</p><div class="price-line"><strong>${money(p.precio)}</strong><small>${p.stock} pzas.</small></div><div class="add-row"><input class="input qty-input" type="number" min="1" max="${p.stock}" value="1" id="addqty-${p.id}" aria-label="Cantidad de ${attr(p.nombre)}" ${available?'':'disabled'}><button class="btn btn-pink" type="button" data-action="add" data-id="${p.id}" ${available?'':'disabled'}>Agregar +</button></div></div></article>`;}
function catalogSection(home=false){let list=state.productos.filter(p=>p.activo);if(home)list=list.slice(0,8);else{if(currentCategory!=='Todos')list=list.filter(p=>p.categoria===currentCategory);if(currentSearch)list=list.filter(p=>[p.nombre,p.descripcion,p.codigo,p.categoria].join(' ').toLowerCase().includes(currentSearch.toLowerCase()));if(currentSort==='precioasc')list.sort((a,b)=>a.precio-b.precio);else if(currentSort==='preciodesc')list.sort((a,b)=>b.precio-a.precio);else if(currentSort==='nombre')list.sort((a,b)=>a.nombre.localeCompare(b.nombre));else list.sort((a,b)=>b.id-a.id);}
return `<section class="section" id="catalogo"><div class="section-head"><div><span class="eyebrow">ELIGE TU PRÓXIMA AVENTURA</span><h2>${home?'Productos destacados':'Explora el catálogo'}</h2></div><span class="muted">${list.length} productos</span></div>${home?'':`<div class="catalog-filters"><div class="chips">${['Todos','Cascos','Accesorios','Refacciones'].map(c=>`<button class="chip ${currentCategory===c?'active':''}" data-action="category" data-value="${c}">${c}</button>`).join('')}</div><div class="filter-input"><input id="searchProducts" placeholder="⌕ Buscar por producto o código..." value="${attr(currentSearch)}" aria-label="Buscar productos"></div><select class="sort" id="sortProducts"><option value="recientes" ${currentSort==='recientes'?'selected':''}>Más recientes</option><option value="precioasc" ${currentSort==='precioasc'?'selected':''}>Menor precio</option><option value="preciodesc" ${currentSort==='preciodesc'?'selected':''}>Mayor precio</option><option value="nombre" ${currentSort==='nombre'?'selected':''}>Nombre A-Z</option></select></div>`}<div class="product-grid">${list.map(card).join('')}</div>${list.length?'':`<div class="empty panel"><span class="emoji">🔍</span><h3>Sin resultados</h3><p>Prueba con otra búsqueda o categoría.</p><button class="btn" data-action="clear-search">Mostrar todos</button></div>`}${home?`<p style="text-align:center;margin-top:30px"><a class="btn btn-outline" href="#catalogo">Ver todo el catálogo →</a></p>`:''}</section>`;}
function homePage(){return `<div class="container"><div class="hero"><div class="hero-copy"><div class="hero-kicker">ACCESORIOS PARA CADA RUTA</div><h1>Tu moto.<br>Tu estilo.<br><em>Tu camino.</em></h1><p>Elige el equipo para tu próxima aventura. Explora productos, arma tu carrito y realiza pedidos de demostración.</p><a href="#catalogo" class="btn btn-pink">Explorar productos ↗</a><div class="hero-footnote">CASCOS &nbsp; / &nbsp; ACCESORIOS &nbsp; / &nbsp; REFACCIONES</div></div><div class="hero-visual"><div class="hero-glow"></div><span class="hero-bike">🏍️</span><span class="hero-stamp">MOTO SHOP · MX</span></div></div><div class="benefits"><div class="benefit"><span class="benefit-icon">🚚</span><div><strong>Envío $30 MXN</strong><small>Simulado en el checkout</small></div></div><div class="benefit"><span class="benefit-icon">📦</span><div><strong>Recoge en tienda</strong><small>Sin costo de envío</small></div></div><div class="benefit"><span class="benefit-icon">🔒</span><div><strong>Compras de prueba</strong><small>Nunca realizamos cargos</small></div></div></div>${banner()}${catalogSection(true)}<section class="section"><div class="section-head"><div><span class="eyebrow">EXPLORA POR TIPO</span><h2>Listo para rodar</h2></div></div><div class="category-grid">${[['Cascos','⛑️'],['Accesorios','🧤'],['Refacciones','⚙️']].map(([c,em])=>`<a class="category-card" href="#catalogo" data-action="goto-category" data-value="${c}"><span class="category-emoji">${em}</span><span><h3>${c}</h3><small>Explorar colección →</small></span></a>`).join('')}</div></section></div>`;}
function catalogPage(){return `<div class="container"><div class="page-hero"><span class="eyebrow">MOTO SHOP / COLECCIONES</span><h1>La tienda</h1><p>Cascos, accesorios y refacciones en un mismo lugar.</p></div>${catalogSection()}</div>`;}
function productPage(id){let p=pById(id),urlParams=new URLSearchParams(location.search),shared=false;if(!p&&urlParams.get('sku')===String(id)){const name=urlParams.get('nombre');if(name){p={id,nombre:name,precio:Math.max(0,Number(urlParams.get('precio'))||0),stock:Math.max(0,Number(urlParams.get('stock'))||0),categoria:urlParams.get('categoria')||'Accesorios',emoji:urlParams.get('icono')||'🏍️',color:'#f2d6e0',descripcion:'Ficha de producto de demostración compartida mediante código QR.',imagenes:[],activo:true,codigo:'QR-'+id};shared=true;}}
if(!p)return `<div class="container"><div class="empty"><div class="emoji">🛵</div><h2>Producto no encontrado</h2><a href="#catalogo" class="btn">Ver catálogo</a></div></div>`;
const photos=p.imagenes||[],src=photos[selectedImage]||null;return `<div class="container"><div class="breadcrumbs"><a href="#inicio">Inicio</a> / <a href="#catalogo">Tienda</a> / ${esc(p.nombre)}</div><section class="detail-layout"><div><div class="detail-visual" style="background:${/^#[0-9a-fA-F]{6}$/.test(p.color)?p.color:'#f6d9e2'}">${src?`<img src="${attr(src)}" alt="${attr(p.nombre)}">`:`<span class="product-emoji">${esc(p.emoji||'🏍️')}</span>`}</div>${photos.length>1?`<div class="thumbs">${photos.map((photo,i)=>`<img class="thumb ${i===selectedImage?'selected':''}" data-action="detail-photo" data-index="${i}" src="${attr(photo)}" alt="Foto ${i+1}">`).join('')}</div>`:''}</div><div class="detail-copy"><span class="eyebrow">${esc(p.categoria)} · ${esc(p.codigo||'')}</span><h1>${esc(p.nombre)}</h1><span class="pill ${p.stock?'positive':'neutral'}">${p.stock?'✓ En existencia':'Agotado'} · ${p.stock} unidades</span><p>${esc(p.descripcion)}</p><div class="price">${money(p.precio)}</div><p class="price-note">Precio base de demostración; en el resumen de compra se agrega IVA 16 %.</p><div class="field" style="max-width:140px"><label for="detailQty">Cantidad</label><input type="number" id="detailQty" min="1" max="${p.stock}" value="1"></div><button class="btn btn-pink" data-action="add-detail" data-id="${p.id}" ${p.stock?'':'disabled'}>🛒 Agregar al carrito</button><div class="share-row"><button class="btn btn-outline" data-action="qr" data-id="${p.id}" ${shared?'data-shared="1"':''}>▦ Ver código QR</button><button class="btn btn-outline" data-action="share" data-id="${p.id}">↗ Compartir producto</button></div>${banner()}${shared?'<p class="muted">Esta ficha procede de un código QR. El inventario en otros dispositivos no se sincroniza. Para comprarlo en tu demo debes tener el artículo también en tu navegador.</p>':''}</div></section></div>`;}
function cartPage(){const {items,subtotal,iva}=cartTotals(),total=+(subtotal+iva).toFixed(2);return `<div class="container"><div class="page-hero"><span class="eyebrow">TUS ELECCIONES</span><h1>Mi carrito <span class="pink">(${items.reduce((s,i)=>s+i.cantidad,0)})</span></h1><p>Revisa cantidades, fotografías y QR de cada artículo.</p></div>${banner()}${items.length?`<div class="layout-side"><div class="panel table-wrap"><table class="data-table"><thead><tr><th>Nombre del producto</th><th>Stock comprado</th><th>Imagen</th><th>Código QR</th><th>Precio total</th><th>Acciones</th></tr></thead><tbody>${items.map(({p,cantidad,total})=>`<tr><td><strong>${esc(p.nombre)}</strong><br><span class="muted">${esc(p.codigo)}</span></td><td><input class="cart-qty" data-qty-id="${p.id}" type="number" min="1" max="${p.stock}" value="${cantidad}" aria-label="Cantidad de ${attr(p.nombre)}"></td><td>${pictureSmall(p)}</td><td><img class="qr-thumbnail" src="${attr(qrSrc(pagesUrl(p),90))}" data-action="qr" data-id="${p.id}" alt="Ver QR de ${attr(p.nombre)}" loading="lazy"></td><td><strong>${money(total)}</strong></td><td><button class="btn btn-outline btn-small" data-action="remove" data-id="${p.id}">Quitar</button></td></tr>`).join('')}</tbody></table></div><aside class="panel pad summary"><h3>Resumen de compra</h3><div class="summary-row"><span>Subtotal</span><strong>${money(subtotal)}</strong></div><div class="summary-row"><span>IVA (16%)</span><strong>${money(iva)}</strong></div><div class="summary-row"><span>Envío</span><span>Se calcula al pagar</span></div><div class="summary-row summary-total"><span>Total sin envío</span><strong>${money(total)}</strong></div><div class="summary-info">Recoger en tienda es gratis o puedes simular entrega a domicilio por $30.</div><button class="btn btn-pink btn-full" data-action="checkout">Continuar con el pedido →</button><p><a href="#catalogo" class="btn btn-outline btn-full">← Seguir comprando</a></p></aside></div>`:`<div class="panel empty"><span class="emoji">🛒</span><h3>Tu carrito está vacío</h3><p>Agrega productos desde nuestro catálogo.</p><a href="#catalogo" class="btn btn-pink">Explorar productos</a></div>`}</div>`;}
function checkoutPage(){if(!getUser())return authPage('login','Para finalizar tu compra, inicia sesión. Tu carrito se conserva.');const {items,subtotal,iva}=cartTotals();if(!items.length)return cartPage();return `<div class="container"><div class="page-hero"><span class="eyebrow">FINALIZA TU PEDIDO</span><h1>Checkout <span class="pink">demo</span></h1><p>No se solicitarán datos bancarios ni se realizarán cargos.</p></div>${banner()}<div class="layout-side"><div class="panel pad"><form id="checkoutForm" data-form="checkout"><div class="section-head"><h2 style="font-size:23px">Datos de entrega</h2></div><div class="grid2"><div class="field"><label>Nombre completo *</label><input name="nombre" maxlength="80" value="${attr(getUser().nombre)}" required></div><div class="field"><label>Correo *</label><input type="email" name="correo" maxlength="100" value="${attr(getUser().email)}" required></div></div><div class="field"><label>Teléfono (solo demostración)</label><input name="telefono" inputmode="tel" maxlength="18" placeholder="10 dígitos" pattern="[0-9 +()-]{7,18}"></div><div class="line"></div><h3>¿Cómo quieres recibirlo?</h3><div class="field"><label>Entrega</label><select name="entrega" id="deliveryChoice"><option value="recoger">Recoger en tienda — $0</option><option value="domicilio">Domicilio — $30</option></select></div><div class="field hidden" id="deliveryAddress"><label>Dirección de prueba *</label><textarea name="direccion" maxlength="250" placeholder="Calle, número, colonia, ciudad y referencias (usa datos ficticios)"></textarea><small>No escribas tu dirección real: esta página es una demostración pública.</small></div><div class="line"></div><h3>Forma de pago (simulada)</h3><div class="field"><label>Método</label><select name="metodo"><option value="efectivo">Efectivo al recibir — simulación</option><option value="tarjeta">Tarjeta de prueba — aprobación simulada</option></select><small>No se pedirán números de tarjeta.</small></div><button class="btn btn-pink btn-full" type="submit">Confirmar pedido de prueba →</button></form></div><aside class="panel pad summary"><h3>Tu pedido</h3>${items.map(({p,cantidad,total})=>`<div class="summary-row"><span>${cantidad} × ${esc(p.nombre)}</span><strong>${money(total)}</strong></div>`).join('')}<div class="line"></div><div class="summary-row"><span>Subtotal</span><strong>${money(subtotal)}</strong></div><div class="summary-row"><span>IVA 16 %</span><strong>${money(iva)}</strong></div><div class="summary-row"><span>Envío</span><strong id="summaryShipping">$0.00</strong></div><div class="summary-row summary-total"><span>Total</span><strong id="summaryCheckoutTotal">${money(subtotal+iva)}</strong></div></aside></div></div>`;}
function userOrdersPage(){const user=getUser();if(!user)return authPage('login','Inicia sesión para consultar tus pedidos.');const orders=state.pedidos.filter(o=>o.usuarioId===user.id).sort((a,b)=>b.id-a.id);return `<div class="container"><div class="page-hero"><span class="eyebrow">MI CUENTA</span><h1>Mis pedidos</h1><p>Historial de tus compras de demostración.</p></div>${banner()}${orders.length?`<div class="panel table-wrap"><table class="data-table"><thead><tr><th>Folio</th><th>Fecha</th><th>Productos</th><th>Método</th><th>Total</th><th>Estado</th><th>Detalle</th></tr></thead><tbody>${orders.map(o=>`<tr><td><strong>${esc(o.folio)}</strong></td><td>${fmtDate(o.fecha)}</td><td>${o.items.reduce((s,i)=>s+i.cantidad,0)} piezas</td><td>${o.metodo==='tarjeta'?'Tarjeta demo':'Efectivo demo'}</td><td>${money(o.total)}</td><td>${statusBadge(o.estado)}</td><td><button class="btn btn-outline btn-small" data-action="receipt" data-id="${o.id}">Ver pedido</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="panel empty"><span class="emoji">📦</span><h3>Aún no tienes pedidos</h3><p>Puedes simular tu primera compra desde el catálogo.</p><a class="btn btn-pink" href="#catalogo">Empezar a comprar</a></div>`}</div>`;}
const statuses={pendiente:'Pendiente de efectivo',pagado:'Pagado (demo)',entregado:'Entregado (demo)',cancelado:'Cancelado'};
function statusBadge(status){return `<span class="pill ${status==='pagado'||status==='entregado'?'positive':status==='pendiente'?'warn':'neutral'}">${esc(statuses[status]||status)}</span>`;}
function authPage(tab='login',text=''){return `<div class="container"><div class="auth-layout"><div class="auth-image"><span class="eyebrow">BIENVENIDO A MOTO SHOP</span><h2>Tu próxima ruta <span>comienza aquí.</span></h2><p>Crea una cuenta de prueba y disfruta todas las funciones de la tienda sin pagar.</p><div class="huge">🏍️</div></div><div class="auth-form"><div class="auth-tabs"><button data-action="auth-tab" data-value="login" class="${tab==='login'?'active':''}">Iniciar sesión</button><button data-action="auth-tab" data-value="registro" class="${tab==='registro'?'active':''}">Registrarme</button></div>${tab==='registro'?`<h2>Crear cuenta</h2><p>Registro simulado almacenado en este navegador.</p><form data-form="register"><div class="field"><label>Nombre completo *</label><input name="nombre" minlength="3" maxlength="80" required autocomplete="name"></div><div class="field"><label>Correo electrónico *</label><input type="email" name="email" required maxlength="100" autocomplete="email"></div><div class="field"><label>Contraseña de prueba (mín. 8 caracteres) *</label><input type="password" name="password" minlength="8" maxlength="80" required autocomplete="new-password"></div><button class="btn btn-pink btn-full">Crear cuenta demo</button></form>`:`<h2>¡Qué gusto verte!</h2><p>${esc(text||'Ingresa con una cuenta de demostración.')}</p><form data-form="login"><div class="field"><label>Correo electrónico</label><input type="email" name="email" required autocomplete="username"></div><div class="field"><label>Contraseña</label><input type="password" name="password" required autocomplete="current-password"></div><button class="btn btn-pink btn-full">Ingresar a mi cuenta →</button></form><div class="demo-credentials"><strong>🔑 Acceso de demostración</strong><br>Administrador: <code>admin@demo.com</code> / <code>Admin1234!</code><br>Cliente: <code>cliente@demo.com</code> / <code>Cliente1234!</code><div style="margin-top:7px"><button data-action="demo-login" data-role="admin" class="btn btn-outline btn-small">Entrar como admin</button> <button data-action="demo-login" data-role="cliente" class="btn btn-outline btn-small">Entrar como cliente</button></div></div>`}<p class="form-note">No uses contraseñas reales: este acceso no es seguridad de producción.</p></div></div></div>`;}
function staffAccess(){return ['admin','empleado'].includes(getUser()?.role);}
const menuItems=[['resumen','◫','Resumen'],['productos','◈','Productos'],['pedidos','▤','Pedidos'],['reportes','▥','Reportes'],['usuarios','♙','Usuarios'],['empleados','♧','Empleados'],['notificaciones','♢','Notificaciones'],['bitacora','◎','Bitácora']];
function adminPage(){if(!staffAccess())return authPage('login','Ingresa como administrador o empleado para continuar.');if(!isAdmin()&&!['resumen','pedidos','notificaciones'].includes(adminTab))adminTab='resumen';let allowed=isAdmin()?menuItems:menuItems.filter(i=>['resumen','pedidos','notificaciones'].includes(i[0]));return `<div class="container"><div class="page-hero"><span class="eyebrow">MOTO SHOP / BACK OFFICE</span><h1>Panel <span class="pink">administrativo</span></h1><p>Gestiona todo el comercio de demostración, con inventario y pedidos guardados en este navegador.</p></div>${banner()}<div class="admin-grid"><aside class="admin-menu panel"><h3>MENÚ DE GESTIÓN</h3>${allowed.map(([id,icon,label])=>`<button class="${adminTab===id?'active':''}" data-action="admin-tab" data-value="${id}">${icon} ${label}${id==='notificaciones'&&state.notificaciones.filter(n=>!n.leida).length?` <span class="pill">${state.notificaciones.filter(n=>!n.leida).length}</span>`:''}</button>`).join('')}<hr><button data-action="reset">⟲ Reiniciar demo</button></aside><div class="admin-main">${adminBody()}</div></div></div>`;}
function saleOrders(){return state.pedidos.filter(o=>o.estado!=='cancelado');}
function soldOrders(){return state.pedidos.filter(o=>['pagado','entregado'].includes(o.estado));}
function metrics(orders){let sold=orders.filter(o=>['pagado','entregado'].includes(o.estado));return {ventas:sold.length,ingresos:sold.reduce((s,o)=>s+o.total,0),pendientes:orders.filter(o=>o.estado==='pendiente').length,piezas:sold.reduce((s,o)=>s+o.items.reduce((r,i)=>r+i.cantidad,0),0)};}
function statCards(m){return `<div class="stat-grid"><div class="stat-card"><span class="stat-icon">💰</span><strong>${money(m.ingresos)}</strong><small>Ventas cobradas (demo)</small></div><div class="stat-card"><span class="stat-icon">📦</span><strong>${m.ventas}</strong><small>Pedidos cobrados</small></div><div class="stat-card"><span class="stat-icon">🛒</span><strong>${m.piezas}</strong><small>Unidades vendidas</small></div><div class="stat-card"><span class="stat-icon">⏳</span><strong>${m.pendientes}</strong><small>Pendientes de pago</small></div></div>`;}
function chartSales(orders){const sorted=[...orders].filter(o=>['pagado','entregado'].includes(o.estado));let data=[];for(let i=6;i>=0;i--){let d=new Date();d.setDate(d.getDate()-i);const key=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');data.push({key,label:d.toLocaleDateString('es-MX',{weekday:'short',day:'numeric'}),value:sorted.filter(o=>localDay(o.fecha)===key).reduce((sum,o)=>sum+o.total,0)});}const max=Math.max(1,...data.map(o=>o.value));return `<div class="bar-chart" aria-label="Ventas cobradas en los últimos siete días">${data.map(d=>`<div class="bar-col"><div class="bar" style="height:${Math.max(2,Math.round(d.value/max*100))}%" data-value="${money(d.value)}" title="${money(d.value)}"></div><small>${esc(d.label)}</small></div>`).join('')}</div>`;}
function listOrders(rows,admin=false){return `<div class="admin-list table-wrap"><table class="data-table"><thead><tr><th>Folio</th><th>Cliente</th><th>Fecha</th><th>Pago</th><th>Total</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${rows.length?rows.map(o=>`<tr><td><strong>${esc(o.folio)}</strong></td><td>${esc(o.nombre)}</td><td>${fmtDate(o.fecha)}</td><td>${o.metodo==='tarjeta'?'Tarjeta demo':'Efectivo demo'}</td><td><strong>${money(o.total)}</strong></td><td>${statusBadge(o.estado)}</td><td><div class="inline-actions"><button class="btn btn-outline btn-small" data-action="receipt" data-id="${o.id}">Detalle</button>${admin&&o.estado==='pendiente'?`<button class="btn btn-pink btn-small" data-action="order-pay" data-id="${o.id}">Cobrar</button>`:''}${admin&&o.estado==='pagado'?`<button class="btn btn-outline btn-small" data-action="order-deliver" data-id="${o.id}">Entregar</button>`:''}${admin&&['pendiente','pagado'].includes(o.estado)?`<button class="btn btn-outline btn-small" data-action="order-cancel" data-id="${o.id}">Cancelar</button>`:''}</div></td></tr>`).join(''):'<tr><td colspan="7" class="muted">No existen pedidos en esta sección.</td></tr>'}</tbody></table></div>`;}
function adminBody(){if(adminTab==='resumen'){const m=metrics(state.pedidos);return `<div class="admin-top"><h2>Resumen general</h2><span class="pill">Datos simulados</span></div>${statCards(m)}<div class="admin-two"><div class="admin-list"><h3>📈 Ventas de los últimos 7 días</h3>${chartSales(state.pedidos)}</div><div class="admin-list"><h3>📊 Inventario y actividad</h3><div class="summary-row"><span>Productos activos</span><strong>${state.productos.filter(p=>p.activo).length}</strong></div><div class="summary-row"><span>Productos con bajo stock (≤ 5)</span><strong>${state.productos.filter(p=>p.stock<=5&&p.activo).length}</strong></div><div class="summary-row"><span>Usuarios registrados</span><strong>${state.usuarios.length}</strong></div><div class="summary-row"><span>Pedidos totales</span><strong>${state.pedidos.length}</strong></div><div class="summary-row"><span>Notificaciones sin leer</span><strong>${state.notificaciones.filter(n=>!n.leida).length}</strong></div><button class="btn btn-outline btn-small" data-action="admin-tab" data-value="reportes">Ver reportes →</button></div></div><div style="height:20px"></div><h3>Últimos pedidos</h3>${listOrders(state.pedidos.slice().sort((a,b)=>b.id-a.id).slice(0,5),true)}`;}
if(adminTab==='productos'){const all=[...state.productos].sort((a,b)=>b.id-a.id);return `<div class="admin-top"><h2>Inventario y productos</h2><button class="btn btn-pink" data-action="product-edit">+ Nuevo producto</button></div><div class="admin-list table-wrap"><table class="data-table"><thead><tr><th>Imagen</th><th>Producto</th><th>Categoría</th><th>Precio</th><th>Stock</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${all.map(p=>`<tr><td>${pictureSmall(p)}</td><td><strong>${esc(p.nombre)}</strong><br><span class="muted">${esc(p.codigo||'')}</span></td><td>${esc(p.categoria)}</td><td>${money(p.precio)}</td><td><strong>${p.stock}</strong></td><td><span class="pill ${p.activo?'positive':'neutral'}">${p.activo?'Publicado':'Oculto'}</span></td><td><div class="inline-actions"><button class="btn btn-outline btn-small" data-action="product-edit" data-id="${p.id}">Editar</button><button class="btn btn-outline btn-small" data-action="product-toggle" data-id="${p.id}">${p.activo?'Ocultar':'Mostrar'}</button><button class="btn btn-outline btn-small" data-action="product-delete" data-id="${p.id}">Eliminar</button></div></td></tr>`).join('')}</tbody></table></div>`;}
if(adminTab==='pedidos'){return `<div class="admin-top"><h2>Pedidos y cobros</h2><span class="pill">${state.pedidos.length} pedidos</span></div><div class="demo-info">Al confirmar efectivo, el pedido se registra como pagado (solo para la demo). Cancelarlo devuelve las cantidades al inventario.</div>${listOrders([...state.pedidos].sort((a,b)=>b.id-a.id),true)}`;}
if(adminTab==='reportes'){const orders=filteredOrders(),m=metrics(orders);return `<div class="admin-top"><h2>Reportes de ventas</h2><button class="btn btn-outline btn-small" data-action="csv">↧ Descargar CSV</button></div><div class="admin-list"><form id="reportForm" class="report-controls" data-form="report"><div class="field"><label>Desde</label><input type="date" name="desde" value="${attr(reportFrom)}"></div><div class="field"><label>Hasta</label><input type="date" name="hasta" value="${attr(reportTo)}"></div><button class="btn btn-pink btn-small">Filtrar fechas</button><button class="btn btn-outline btn-small" type="button" data-action="report-clear">Limpiar</button><button class="btn btn-outline btn-small" type="button" data-action="print">Imprimir / PDF</button></form>${statCards(m)}<h3>Pedidos dentro del periodo</h3>${listOrders(orders,false)}<h3 style="margin-top:24px">Productos más vendidos (pedidos cobrados)</h3>${topProducts(orders)}</div>`;}
if(adminTab==='usuarios'||adminTab==='empleados'){const onlyStaff=adminTab==='empleados';const rows=state.usuarios.filter(u=>onlyStaff?u.role==='empleado':u.role!=='empleado');return `<div class="admin-top"><h2>${onlyStaff?'Empleados':'Usuarios registrados'}</h2><button class="btn btn-pink" data-action="user-edit" data-role="${onlyStaff?'empleado':'cliente'}">+ Agregar ${onlyStaff?'empleado':'usuario'}</button></div><div class="admin-list table-wrap"><table class="data-table"><thead><tr><th>Nombre</th><th>Correo</th><th>Rol</th><th>Acceso</th><th>Acciones</th></tr></thead><tbody>${rows.map(u=>`<tr><td><strong>${esc(u.nombre)}</strong></td><td>${esc(u.email)}</td><td><span class="pill">${esc(u.role)}</span></td><td>${u.activo?'Activo':'Bloqueado'}</td><td><div class="inline-actions"><button class="btn btn-outline btn-small" data-action="user-edit" data-id="${u.id}">Editar</button>${u.id!==getUser().id?`<button class="btn btn-outline btn-small" data-action="user-toggle" data-id="${u.id}">${u.activo?'Bloquear':'Activar'}</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`;}
if(adminTab==='notificaciones'){return `<div class="admin-top"><h2>Notificaciones</h2><button class="btn btn-outline btn-small" data-action="notifications-read">Marcar todas como leídas</button></div><div class="admin-list notifications">${state.notificaciones.length?state.notificaciones.map(n=>`<div class="notice-card"><div><strong>${n.leida?'○':'●'} ${esc(n.texto)}</strong><small>${fmtDate(n.fecha)}</small></div>${n.leida?'':`<button class="btn btn-outline btn-small" data-action="notification-read" data-id="${n.id}">Leída</button>`}</div>`).join(''):'<div class="empty">Sin notificaciones por ahora.</div>'}</div>`;}
if(adminTab==='bitacora'){return `<div class="admin-top"><h2>Bitácora de accesos</h2><span class="muted">No se guardan contraseñas en la bitácora.</span></div><div class="admin-list table-wrap"><table class="data-table"><thead><tr><th>Fecha</th><th>Correo</th><th>Resultado</th></tr></thead><tbody>${state.bitacora.length?state.bitacora.map(l=>`<tr><td>${fmtDate(l.fecha)}</td><td>${esc(l.correo)}</td><td>${l.resultado==='ACEPTADO'?'<span class="pill positive">Aceptado</span>':'<span class="pill warn">Denegado</span>'}</td></tr>`).join(''):'<tr><td colspan="3">Sin accesos recientes.</td></tr>'}</tbody></table></div>`;}
return '<p>No se encontró el módulo.</p>';}
function filteredOrders(){let arr=state.pedidos;if(reportFrom)arr=arr.filter(o=>localDay(o.fecha)>=reportFrom);if(reportTo)arr=arr.filter(o=>localDay(o.fecha)<=reportTo);return [...arr].sort((a,b)=>b.id-a.id);}
function topProducts(orders){const counts=new Map();orders.filter(o=>['pagado','entregado'].includes(o.estado)).forEach(o=>o.items.forEach(i=>{let k=i.nombre;counts.set(k,(counts.get(k)||0)+i.cantidad);}));return [...counts.entries()].sort((a,b)=>b[1]-a[1]).length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Producto</th><th>Unidades vendidas</th></tr></thead><tbody>${[...counts.entries()].sort((a,b)=>b[1]-a[1]).map(([name,v])=>`<tr><td>${esc(name)}</td><td><strong>${v}</strong></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Aún no hay ventas cobradas en el periodo.</p>';}
function profilePage(){const u=getUser();if(!u)return authPage();const rows=state.registros.filter(r=>r.usuarioId===u.id);return `<div class="container"><div class="page-hero"><span class="eyebrow">MI PERFIL</span><h1>Hola, ${esc(u.nombre.split(' ')[0])}</h1><p>${esc(u.email)} · ${esc(u.role)}</p></div>${banner()}<div class="admin-top"><h2>Mis registros personales de prueba</h2><button class="btn btn-pink" data-action="registro-edit">+ Nuevo registro</button></div><div class="panel table-wrap"><table class="data-table"><thead><tr><th>Nombre</th><th>Edad</th><th>Sexo</th><th>Teléfono</th><th>Acciones</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr><td>${esc(r.nombre+' '+r.apellidoP+' '+r.apellidoM)}</td><td>${r.edad}</td><td>${esc(r.sexo)}</td><td>${esc(r.telefono)}</td><td><button class="btn btn-outline btn-small" data-action="registro-edit" data-id="${r.id}">Editar</button> <button class="btn btn-outline btn-small" data-action="registro-delete" data-id="${r.id}">Eliminar</button></td></tr>`).join(''):'<tr><td colspan="5">Todavía no hay registros personales.</td></tr>'}</tbody></table></div></div>`;}
function receiptContent(o){return `<div class="receipt" id="receipt"><div style="text-align:center"><h2 style="font:900 29px Outfit;margin:0">MOTO<span class="pink">SHOP</span></h2><p class="muted">TICKET DE DEMOSTRACIÓN · DOCUMENTO NO FISCAL</p></div><div class="line"></div><div class="summary-row"><span>Folio</span><strong>${esc(o.folio)}</strong></div><div class="summary-row"><span>Fecha</span><strong>${fmtDate(o.fecha)}</strong></div><div class="summary-row"><span>Cliente</span><strong>${esc(o.nombre)}</strong></div><div class="summary-row"><span>Correo</span><strong>${esc(o.correo)}</strong></div><div class="summary-row"><span>Estado</span><strong>${esc(statuses[o.estado])}</strong></div><div class="summary-row"><span>Método</span><strong>${o.metodo==='tarjeta'?'Tarjeta de prueba':'Efectivo de prueba'}</strong></div><div class="summary-row"><span>Entrega</span><strong>${o.entrega==='domicilio'?'Domicilio demo':'Recoger en tienda'}</strong></div><div class="line"></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Artículo</th><th>Cant.</th><th>Precio</th><th>Importe</th></tr></thead><tbody>${o.items.map(i=>`<tr><td>${esc(i.nombre)}</td><td>${i.cantidad}</td><td>${money(i.precio)}</td><td>${money(i.precio*i.cantidad)}</td></tr>`).join('')}</tbody></table></div><div class="summary-row"><span>Subtotal</span><strong>${money(o.subtotal)}</strong></div><div class="summary-row"><span>IVA 16 %</span><strong>${money(o.iva)}</strong></div><div class="summary-row"><span>Envío</span><strong>${money(o.envio)}</strong></div><div class="summary-row summary-total"><span>TOTAL</span><strong>${money(o.total)}</strong></div><p class="muted" style="font-size:11px">Este ticket es parte de una simulación. No acredita pago, compra ni entrega reales.</p></div>`;}
function receiptPage(id){const o=orderById(id),u=getUser();if(!o||(!isAdmin()&&!staffAccess()&&o.usuarioId!==u?.id))return `<div class="container empty"><h2>Pedido no disponible</h2><a href="#pedidos" class="btn">Volver a mis pedidos</a></div>`;return `<div class="container"><div class="page-hero"><span class="eyebrow">MOTO SHOP · PEDIDOS</span><h1>Ticket <span class="pink">${esc(o.folio)}</span></h1><p>Compra de demostración, sin efectos fiscales ni cobros reales.</p></div><div class="panel pad" style="max-width:700px;margin:0 auto 30px">${receiptContent(o)}<div class="share-row no-print"><button class="btn btn-pink" data-action="print">🖨 Imprimir / guardar PDF</button><button class="btn btn-outline" data-action="ticket-email" data-id="${o.id}">✉ Simular correo</button><a href="#${staffAccess()?'admin':'pedidos'}" class="btn btn-outline">← Regresar</a></div></div></div>`;}
function qrModal(p){const u=pagesUrl(p);openModal('Código QR del producto',`<div style="text-align:center"><span class="eyebrow">FICHA DE PRODUCTO · QR</span><h3>${esc(p.nombre)}</h3><img class="qr-large" src="${attr(qrSrc(u,280))}" alt="Código QR para ${attr(p.nombre)}"><p><strong>${money(p.precio)} · ${p.stock} unidades</strong></p><p class="qr-info">Escanea este código con otro celular para abrir una ficha de demostración del producto. Si el servicio externo de QR no carga, usa el enlace.</p><p><a target="_blank" rel="noopener noreferrer" href="${attr(u)}" class="btn btn-outline btn-small">Abrir ficha QR ↗</a> <button class="btn btn-pink btn-small" data-action="copy" data-copy="${attr(u)}">Copiar enlace</button></p></div>`);}
function productEditModal(p){const isNew=!p;p=p||{id:0,nombre:'',codigo:'',categoria:'Cascos',precio:'',stock:'',descripcion:'',emoji:'🏍️',color:'#f3d7e2',activo:true,imagenes:[]};openModal(isNew?'Nuevo producto':'Editar producto',`<form data-form="product" data-id="${p.id}"><div class="grid2"><div class="field"><label>Nombre *</label><input name="nombre" value="${attr(p.nombre)}" maxlength="130" required></div><div class="field"><label>Código *</label><input name="codigo" value="${attr(p.codigo)}" maxlength="35" required></div><div class="field"><label>Categoría</label><select name="categoria">${['Cascos','Accesorios','Refacciones'].map(v=>`<option ${p.categoria===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Precio base (MXN) *</label><input type="number" name="precio" min="0.01" max="999999" step="0.01" value="${p.precio}" required></div><div class="field"><label>Stock *</label><input type="number" name="stock" min="0" max="999999" step="1" value="${p.stock}" required></div><div class="field"><label>Emoji ilustrativo</label><input name="emoji" maxlength="6" value="${attr(p.emoji)}"></div></div><div class="field"><label>Descripción</label><textarea name="descripcion" maxlength="500">${esc(p.descripcion)}</textarea></div><div class="field"><label>Imagen 1 (opcional)</label><input type="file" name="imagen1" accept="image/png,image/jpeg,image/webp"><small>Las fotos se guardan en el navegador (hasta 3, comprimidas). No se verán en otros dispositivos.</small></div><div class="grid2"><div class="field"><label>Imagen 2 (opcional)</label><input type="file" name="imagen2" accept="image/png,image/jpeg,image/webp"></div><div class="field"><label>Imagen 3 (opcional)</label><input type="file" name="imagen3" accept="image/png,image/jpeg,image/webp"></div></div>${p.imagenes.length?`<p class="muted">${p.imagenes.length} foto(s) guardada(s). Puedes mantenerlas o sustituir todas.</p><label class="field"><input type="checkbox" name="clearImages" style="width:auto;min-height:auto"> Borrar fotos anteriores</label>`:''}<button class="btn btn-pink btn-full">Guardar producto</button></form>`);}
function userEditModal(u,role='cliente'){u=u||{id:0,nombre:'',email:'',role,activo:true};openModal(u.id?'Editar usuario':'Crear usuario de prueba',`<form data-form="user" data-id="${u.id}"><div class="field"><label>Nombre</label><input name="nombre" required maxlength="80" value="${attr(u.nombre)}"></div><div class="field"><label>Correo electrónico</label><input type="email" name="email" required maxlength="100" value="${attr(u.email)}"></div><div class="field"><label>Rol</label><select name="role">${['cliente','empleado','admin'].map(r=>`<option value="${r}" ${u.role===r?'selected':''}>${r}</option>`).join('')}</select></div><div class="field"><label>Contraseña ${u.id?'(dejar vacío para conservar)':''}</label><input type="password" name="password" ${u.id?'':'required'} minlength="8" maxlength="80"></div><button class="btn btn-pink btn-full">Guardar usuario</button></form>`);}
function registroEditModal(r){r=r||{id:0,nombre:'',apellidoP:'',apellidoM:'',edad:'',sexo:'',telefono:''};openModal('Registro personal de prueba',`<form data-form="registro" data-id="${r.id}"><div class="grid2"><div class="field"><label>Nombre *</label><input name="nombre" required maxlength="70" value="${attr(r.nombre)}"></div><div class="field"><label>Apellido paterno *</label><input name="apellidoP" required maxlength="70" value="${attr(r.apellidoP)}"></div><div class="field"><label>Apellido materno *</label><input name="apellidoM" required maxlength="70" value="${attr(r.apellidoM)}"></div><div class="field"><label>Edad *</label><input name="edad" type="number" min="1" max="110" required value="${r.edad}"></div><div class="field"><label>Sexo *</label><select name="sexo"><option value="" ${!r.sexo?'selected':''}>Selecciona</option>${['Femenino','Masculino','Otro','Prefiero no decirlo'].map(s=>`<option ${r.sexo===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>Teléfono ficticio *</label><input name="telefono" maxlength="20" value="${attr(r.telefono)}" required></div></div><p class="form-note">Usa datos ficticios. Guardado local, no apto para información personal real.</p><button class="btn btn-pink btn-full">Guardar registro</button></form>`);}
function logout(){session=null;sessionStorage.removeItem(SESSION);toast('Sesión de prueba cerrada.');route('inicio');}
async function hashPass(p){const text='MotoShopDemoV1|'+p;const buff=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text));return [...new Uint8Array(buff)].map(x=>x.toString(16).padStart(2,'0')).join('');}
async function login(email,pass){let u=state.usuarios.find(u=>u.email.toLowerCase()===email.toLowerCase());if(!u||!u.activo||u.hash!==(await hashPass(pass))){audit(email,false);toast('Credenciales de demostración incorrectas.','err');return;}audit(email,true);session={userId:u.id};sessionStorage.setItem(SESSION,JSON.stringify(session));toast('¡Bienvenido, '+u.nombre.split(' ')[0]+'!');closeModal();route(staffAccess()?'admin':'inicio');}
function makeOrder(form){const u=getUser();if(!u){route('login');return;}const {items,subtotal,iva}=cartTotals();if(!items.length){route('carrito');return;}const nombre=String(form.get('nombre')||'').trim(),correo=String(form.get('correo')||'').trim(),telefono=String(form.get('telefono')||'').trim(),entrega=String(form.get('entrega')||'recoger'),metodo=String(form.get('metodo')||'efectivo'),direccion=String(form.get('direccion')||'').trim();if(!nombre||!/^\S+@\S+\.\S+$/.test(correo)){toast('Completa nombre y correo válidos.','err');return;}if(entrega==='domicilio'&&!direccion){toast('Ingresa una dirección ficticia para la demostración.','err');return;}
if(!['domicilio','recoger'].includes(entrega)||!['efectivo','tarjeta'].includes(metodo)){toast('Opciones de pedido no válidas.','err');return;}for(const {p,cantidad} of items){const actual=pById(p.id);if(!actual||actual.stock<cantidad){toast('El inventario cambió. Revisa tu carrito.','err');route('carrito');return;}}
const envio=entrega==='domicilio'?30:0,total=+(subtotal+iva+envio).toFixed(2);const id=++state.secuencia,folio='MS-'+new Date().getFullYear()+'-'+id;
const pedido={id,folio,fecha:ts(),usuarioId:u.id,nombre,correo,telefono,entrega,metodo,direccion:entrega==='domicilio'?direccion:'',subtotal,iva,envio,total,estado:metodo==='tarjeta'?'pagado':'pendiente',adminVisto:false,correoDemo:false,items:items.map(({p,cantidad})=>({id:p.id,nombre:p.nombre,codigo:p.codigo,categoria:p.categoria,precio:p.precio,cantidad}))};
items.forEach(({p,cantidad})=>pById(p.id).stock-=cantidad);state.pedidos.unshift(pedido);state.carrito=[];notify(`Nuevo pedido ${folio} · ${money(total)} · ${metodo==='tarjeta'?'tarjeta aprobada (simulada)':'pendiente de efectivo'}`);persist();toast('Pedido '+folio+' creado correctamente (simulación).');route('ticket/'+id);}
function changeOrder(id,action){const o=orderById(id);if(!o||!staffAccess())return;if(action==='pay'&&o.estado==='pendiente'){o.estado='pagado';notify(`${o.folio}: efectivo recibido (simulación)`);}else if(action==='deliver'&&o.estado==='pagado'){o.estado='entregado';notify(`${o.folio}: entrega simulada completada`);}else if(action==='cancel'&&['pagado','pendiente'].includes(o.estado)){if(!confirm(`¿Cancelar ${o.folio} y devolver las unidades al stock?`))return;o.estado='cancelado';o.items.forEach(i=>{const p=pById(i.id);if(p)p.stock+=i.cantidad;});notify(`${o.folio}: cancelado; inventario repuesto`);}else {toast('Esta transición no está permitida.','err');return;}persist();toast('Pedido actualizado.');render();}
function download(name,content,type='text/plain;charset=utf-8'){const b=new Blob([content],{type});const url=URL.createObjectURL(b);const link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCSV(){const rows=[['Folio','Fecha','Cliente','Correo','Estado','Metodo','Entrega','Subtotal','IVA','Envio','Total','Cantidad de piezas']];filteredOrders().forEach(o=>rows.push([o.folio,o.fecha,o.nombre,o.correo,statuses[o.estado],o.metodo,o.entrega,o.subtotal,o.iva,o.envio,o.total,o.items.reduce((sum,i)=>sum+i.cantidad,0)]));const cell=v=>{let str=String(v??'');if(/^[=+@\-\t\r]/.test(str))str="'"+str;return '"'+str.replace(/"/g,'""')+'"';};download('reporte_motoshop_'+today()+'.csv','\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('Reporte CSV descargado.');}
async function compressedPhoto(file){if(!file)return null;if(!/^image\/(jpeg|png|webp)$/.test(file.type))throw Error('Solo se admiten imágenes JPG, PNG y WebP.');if(file.size>6e6)throw Error('La imagen supera 6 MB.');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();let scale=Math.min(1,650/Math.max(img.width,img.height)),w=Math.max(1,Math.round(img.width*scale)),h=Math.max(1,Math.round(img.height*scale));const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;canvas.getContext('2d').drawImage(img,0,0,w,h);return canvas.toDataURL('image/jpeg',.68);}finally{URL.revokeObjectURL(url);}}
function doShare(p){const url=pagesUrl(p);if(navigator.share){navigator.share({title:p.nombre,text:'Ficha de producto Moto Shop (demo)',url}).catch(()=>{});}else copyText(url);}
async function copyText(s){try{await navigator.clipboard.writeText(s);toast('Enlace copiado.');}catch(e){openModal('Copiar enlace',`<div class="field"><label>Selecciona y copia esta URL</label><textarea readonly rows="4">${esc(s)}</textarea></div>`);}}
function flashMissing(){toast('Esta función no está disponible en la demostración.','err');}
function confirmReset(){if(!confirm('¿Reiniciar TODA la tienda de demostración? Se borrarán usuarios creados, fotos, carrito, pedidos y reportes de este navegador.'))return;state=initState();session=null;sessionStorage.removeItem(SESSION);localStorage.removeItem(STORAGE);persist();currentCategory='Todos';currentSearch='';currentSort='recientes';adminTab='resumen';toast('Tienda restaurada a los datos iniciales.');route('inicio');}
function accountPopup(){const u=getUser();if(!u){route('login');return;}openModal('Mi cuenta',`<p>Hola, <strong>${esc(u.nombre)}</strong></p><p class="muted">${esc(u.email)} · ${esc(u.role)}</p><div class="line"></div><div class="grid2"><button class="btn btn-outline" data-action="route" data-to="perfil">♙ Mi perfil</button><button class="btn btn-outline" data-action="route" data-to="pedidos">📦 Mis pedidos</button>${staffAccess()?'<button class="btn btn-outline" data-action="route" data-to="admin">⚙ Administración</button>':''}<button class="btn btn-danger" data-action="logout">Salir de mi cuenta</button></div>`);}
async function handleForm(form){const data=new FormData(form),type=form.dataset.form;
if(type==='login'){await login(String(data.get('email')||'').trim(),String(data.get('password')||''));return;}
if(type==='register'){const name=String(data.get('nombre')||'').trim(),email=String(data.get('email')||'').trim().toLowerCase(),password=String(data.get('password')||'');if(name.length<3||!/^\S+@\S+\.\S+$/.test(email)||password.length<8){toast('Revisa los datos de registro.','err');return;}if(state.usuarios.some(u=>u.email.toLowerCase()===email)){toast('Este correo ya está registrado en la demo.','err');return;}const id=uid();state.usuarios.push({id,nombre:name,email,hash:await hashPass(password),role:'cliente',activo:true});persist();session={userId:id};sessionStorage.setItem(SESSION,JSON.stringify(session));toast('Cuenta de demostración creada.');route('inicio');return;}
if(type==='checkout'){makeOrder(data);return;}
if(type==='report'){const from=String(data.get('desde')||''),to=String(data.get('hasta')||'');if(from&&to&&from>to){toast('La fecha inicial no puede ser posterior a la final.','err');return;}reportFrom=from;reportTo=to;toast('Fechas aplicadas.');render();return;}
if(type==='product'&&isAdmin()){let id=Number(form.dataset.id),p=id?pById(id):null;const nombre=String(data.get('nombre')||'').trim(),codigo=String(data.get('codigo')||'').trim().toUpperCase(),precio=Number(data.get('precio')),stock=Number(data.get('stock')),descripcion=String(data.get('descripcion')||'').trim(),categoria=String(data.get('categoria')||'');if(!nombre||!codigo||!['Cascos','Accesorios','Refacciones'].includes(categoria)||!Number.isFinite(precio)||precio<=0||precio>999999||!Number.isInteger(stock)||stock<0||stock>999999){toast('Revisa nombre, categoría, precio y stock.','err');return;}if(state.productos.some(prod=>prod.codigo===codigo&&prod.id!==id)){toast('Ya existe un producto con ese código.','err');return;}
let imgs=p?.imagenes?.slice()||[];if(data.get('clearImages'))imgs=[];const newImgs=[];try{for(let i=1;i<=3;i++){let f=data.get('imagen'+i);if(f instanceof File&&f.size)newImgs.push(await compressedPhoto(f));}}catch(e){toast(e.message,'err');return;}if(newImgs.length)imgs=newImgs;let values={nombre,codigo,precio:+precio.toFixed(2),stock,descripcion,categoria,emoji:String(data.get('emoji')||'🏍️').slice(0,6),imagenes:imgs};let original=p?structuredClone(p):null;if(p)Object.assign(p,values);else{p={id:uid(),activo:true,color:'#f3dce4',...values};state.productos.unshift(p);}if(!persist()){if(original)Object.assign(p,original);else state.productos=state.productos.filter(x=>x!==p);return;}closeModal();toast('Producto guardado.');render();return;}
if(type==='user'&&isAdmin()){let id=Number(form.dataset.id),user=state.usuarios.find(u=>u.id===id),nombre=String(data.get('nombre')||'').trim(),email=String(data.get('email')||'').trim().toLowerCase(),role=String(data.get('role')||''),password=String(data.get('password')||'');if(!nombre||!/^\S+@\S+\.\S+$/.test(email)||!['cliente','empleado','admin'].includes(role)||(!user&&password.length<8)||(password&&password.length<8)){toast('Completa correctamente todos los datos.','err');return;}if(user?.id===getUser().id&&role!=='admin'){toast('No puedes quitarte tu propio permiso de administrador.','err');return;}if(state.usuarios.some(u=>u.email===email&&u.id!==id)){toast('El correo ya existe.','err');return;}const updates={nombre,email,role};if(password)updates.hash=await hashPass(password);if(user)Object.assign(user,updates);else state.usuarios.push({id:uid(),activo:true,...updates});persist();closeModal();toast('Usuario guardado.');render();return;}
if(type==='registro'){const u=getUser();if(!u)return;let id=Number(form.dataset.id),registro=state.registros.find(r=>r.id===id&&r.usuarioId===u.id);let nombre=String(data.get('nombre')||'').trim(),apellidoP=String(data.get('apellidoP')||'').trim(),apellidoM=String(data.get('apellidoM')||'').trim(),edad=Number(data.get('edad')),sexo=String(data.get('sexo')||''),telefono=String(data.get('telefono')||'').trim();if(!nombre||!apellidoP||!apellidoM||!Number.isInteger(edad)||edad<1||edad>110||!sexo||!telefono){toast('Completa los datos personales de prueba.','err');return;}let fields={nombre,apellidoP,apellidoM,edad,sexo,telefono};if(registro)Object.assign(registro,fields);else state.registros.push({id:uid(),usuarioId:u.id,...fields});persist();closeModal();toast('Registro guardado.');render();return;}
}
function handleAction(el){const a=el.dataset.action,id=Number(el.dataset.id||0),p=pById(id);
if(a==='close-modal'){closeModal();return;}
if(a==='route'){closeModal();route(el.dataset.to);return;}
if(a==='logout'){closeModal();logout();return;}
if(a==='product'){selectedImage=0;route('producto/'+id);return;}
if(a==='goto-category'){currentCategory=el.dataset.value;closeModal();route('catalogo');return;}
if(a==='category'){currentCategory=el.dataset.value;render();return;}
if(a==='clear-search'){currentSearch='';currentCategory='Todos';render();return;}
if(a==='add'){const field=document.getElementById('addqty-'+id);addCart(id,Number(field?.value||1));return;}
if(a==='add-detail'){addCart(id,Number(document.getElementById('detailQty')?.value||1));return;}
if(a==='favorite'){if(state.favoritos.includes(id))state.favoritos=state.favoritos.filter(x=>x!==id);else state.favoritos.push(id);persist();render();return;}
if(a==='detail-photo'){selectedImage=Number(el.dataset.index)||0;render();return;}
if(a==='share'&&p){doShare(p);return;}
if(a==='qr'){let product=p;if(!product){let q=new URLSearchParams(location.search);if(q.get('sku')===String(id))product={id,nombre:q.get('nombre')||'Producto de demostración',precio:Number(q.get('precio'))||0,stock:Number(q.get('stock'))||0,emoji:q.get('icono')||'🏍️',categoria:q.get('categoria')||'Accesorios'};}if(product)qrModal(product);return;}
if(a==='copy'){copyText(el.dataset.copy||'');return;}
if(a==='remove'){removeCart(id);return;}
if(a==='checkout'){route('checkout');return;}
if(a==='auth-tab'){app.innerHTML=authPage(el.dataset.value);return;}
if(a==='demo-login'){login(el.dataset.role==='admin'?'admin@demo.com':'cliente@demo.com',el.dataset.role==='admin'?'Admin1234!':'Cliente1234!');return;}
if(a==='admin-tab'){if(staffAccess()){adminTab=el.dataset.value;render();}return;}
if(a==='receipt'){closeModal();route('ticket/'+id);return;}
if(a==='print'){window.print();return;}
if(a==='ticket-email'){let order=orderById(id),u=getUser();if(!order||(!staffAccess()&&order.usuarioId!==u?.id))return;order.correoDemo=true;persist();openModal('Correo de ticket simulado',`<p class="pill">SIMULACIÓN · NO ENVIADO</p><p>Se preparó una vista del ticket para <strong>${esc(order.correo)}</strong>, pero no se ha enviado ningún correo real.</p><p><strong>Asunto:</strong> Moto Shop — Ticket de prueba ${esc(order.folio)}</p><p class="muted">Puedes utilizar el botón Imprimir / PDF de la página del ticket para guardar una copia.</p><button class="btn btn-pink" data-action="close-modal">Entendido</button>`);return;}
if(a==='order-pay'){changeOrder(id,'pay');return;}
if(a==='order-deliver'){changeOrder(id,'deliver');return;}
if(a==='order-cancel'){changeOrder(id,'cancel');return;}
if(a==='product-edit'&&isAdmin()){productEditModal(p);return;}
if(a==='product-toggle'&&isAdmin()&&p){p.activo=!p.activo;persist();toast('Visibilidad actualizada.');render();return;}
if(a==='product-delete'&&isAdmin()&&p){if(!confirm('¿Eliminar el producto «'+p.nombre+'»? Los pedidos históricos conservarán su detalle.'))return;state.productos=state.productos.filter(x=>x.id!==id);state.carrito=state.carrito.filter(x=>x.id!==id);persist();toast('Producto eliminado.');render();return;}
if(a==='user-edit'&&isAdmin()){userEditModal(state.usuarios.find(u=>u.id===id),el.dataset.role||'cliente');return;}
if(a==='user-toggle'&&isAdmin()){let u=state.usuarios.find(x=>x.id===id);if(!u||u.id===getUser()?.id)return;u.activo=!u.activo;persist();toast('Acceso de usuario actualizado.');render();return;}
if(a==='notifications-read'&&staffAccess()){state.notificaciones.forEach(n=>n.leida=true);persist();render();return;}
if(a==='notification-read'&&staffAccess()){let n=state.notificaciones.find(n=>n.id===id);if(n)n.leida=true;persist();render();return;}
if(a==='report-clear'){reportFrom='';reportTo='';render();return;}
if(a==='csv'&&isAdmin()){exportCSV();return;}
if(a==='registro-edit'){const r=state.registros.find(r=>r.id===id&&r.usuarioId===getUser()?.id);registroEditModal(r);return;}
if(a==='registro-delete'){let r=state.registros.find(r=>r.id===id&&r.usuarioId===getUser()?.id);if(r&&confirm('¿Eliminar este registro de prueba?')){state.registros=state.registros.filter(x=>x!==r);persist();render();}return;}
if(a==='exportar'){download('MotoShop_respaldo_demo_'+today()+'.json',JSON.stringify({tipo:'respaldo_de_demostracion_no_sincronizado',exportado:ts(),productos:state.productos,pedidos:state.pedidos,registros:state.registros},null,2),'application/json;charset=utf-8');toast('Copia de datos demo descargada.');return;}
if(a==='reset'){confirmReset();return;}
}
function render(){let hash=decodeURIComponent(location.hash.slice(1));if(!hash){const params=new URLSearchParams(location.search);hash=params.has('sku')?'producto/'+params.get('sku'):'inicio';}syncHeader();document.getElementById('mobileMenu').classList.add('hidden');let content;if(hash==='inicio')content=homePage();else if(hash==='catalogo')content=catalogPage();else if(hash==='carrito')content=cartPage();else if(hash==='checkout')content=checkoutPage();else if(hash==='login'||hash==='registro')content=authPage(hash);else if(hash==='pedidos')content=userOrdersPage();else if(hash==='admin')content=adminPage();else if(hash==='perfil')content=profilePage();else if(hash.startsWith('producto/'))content=productPage(hash.split('/')[1]);else if(hash.startsWith('ticket/'))content=receiptPage(hash.split('/')[1]);else content=`<div class="container empty"><h2>Esta página no existe</h2><a href="#inicio" class="btn">Volver al inicio</a></div>`;app.innerHTML=content;syncHeader();}
document.addEventListener('click',event=>{const btn=event.target.closest('[data-action]');if(btn){if(btn.tagName==='A')event.preventDefault();event.stopPropagation();handleAction(btn);}});
document.addEventListener('submit',event=>{const form=event.target.closest('[data-form]');if(form){event.preventDefault();const button=form.querySelector('[type=submit]');if(button)button.disabled=true;Promise.resolve(handleForm(form)).catch(e=>{console.error(e);toast('Ocurrió un error al procesar la acción de prueba.','err');}).finally(()=>{if(button?.isConnected)button.disabled=false;});}});
document.addEventListener('change',event=>{const target=event.target;if(target.matches('[data-qty-id]')){updateQty(target.dataset.qtyId,target.value);}if(target.id==='deliveryChoice'){const isHome=target.value==='domicilio';document.getElementById('deliveryAddress')?.classList.toggle('hidden',!isHome);const totals=cartTotals();document.getElementById('summaryShipping').textContent=money(isHome?30:0);document.getElementById('summaryCheckoutTotal').textContent=money(totals.subtotal+totals.iva+(isHome?30:0));}if(target.id==='sortProducts'){currentSort=target.value;render();}});
document.addEventListener('input',event=>{if(event.target.id==='searchProducts'){currentSearch=event.target.value;const cursor=event.target.selectionStart;render();const next=document.getElementById('searchProducts');if(next){next.focus();next.setSelectionRange(cursor,cursor);}}});
window.addEventListener('hashchange',()=>{selectedImage=0;render();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
modalHost.addEventListener('click',e=>{if(e.target===modalHost)closeModal();});
document.getElementById('accountBtn').addEventListener('click',accountPopup);
document.getElementById('mobileToggle').addEventListener('click',()=>document.getElementById('mobileMenu').classList.toggle('hidden'));
document.getElementById('themeToggle').addEventListener('click',()=>{document.body.classList.toggle('night');localStorage.setItem('motoshop_theme',document.body.classList.contains('night')?'dark':'light');syncHeader();});
if(localStorage.getItem('motoshop_theme')==='dark')document.body.classList.add('night');
if(!localStorage.getItem(STORAGE))persist();
render();
})();